// Generated for you: ordinary Three.js materials, owned by this game.
import { MeshStandardMaterial } from "three";
import { palette } from "./palette.js";

export function createMaterials() {
  return {
    arena: new MeshStandardMaterial({ color: palette.arena, metalness: 0.35, roughness: 0.62 }),
    accent: new MeshStandardMaterial({
      color: palette.accent,
      emissive: palette.accent,
      emissiveIntensity: 0.24,
      metalness: 0.2,
      roughness: 0.38,
    }),
    hostile: new MeshStandardMaterial({
      color: palette.hostile,
      emissive: palette.hostile,
      emissiveIntensity: 0.7,
      metalness: 0.1,
      roughness: 0.3,
    }),
    player: new MeshStandardMaterial({
      color: palette.player,
      emissive: palette.player,
      emissiveIntensity: 0.22,
      metalness: 0.35,
      roughness: 0.34,
    }),
    shadow: new MeshStandardMaterial({ color: 0x101820, metalness: 0.5, roughness: 0.7 }),
    trim: new MeshStandardMaterial({
      color: palette.accent,
      emissive: palette.accent,
      emissiveIntensity: 0.45,
      metalness: 0.45,
      roughness: 0.28,
    }),
  };
}
// Generated for you. Keep the six palette roles coherent when you repaint the arena.
export const palette = {
  skyHigh: 0x263449,
  skyLow: 0x101820,
  arena: 0x18232d,
  player: 0x64d8cb,
  hostile: 0xff6b7a,
  accent: 0xf6c85f,
} as const;
import type { CollisionShape3D, IPhysicsBodyHandle, IPhysicsContext } from "@threenative/physics";
import type { Vector3 } from "three";

export type SpacePoint = Pick<Vector3, "x" | "y" | "z">;

export interface IRayHit {
  readonly body: IPhysicsBodyHandle;
  readonly distance: number;
  readonly entity?: string;
  readonly normal: SpacePoint;
  readonly position: SpacePoint;
}

export interface IShapeHit {
  readonly body: IPhysicsBodyHandle;
  readonly entity?: string;
  readonly position?: SpacePoint;
}

export interface IPhysicsDirectSpaceState {
  intersectRay(options: {
    readonly collisionMask?: number;
    readonly from: SpacePoint;
    readonly maxResults?: number;
    readonly to: SpacePoint;
  }): IRayHit | undefined;
  intersectShape(options: {
    readonly collisionMask?: number;
    readonly maxResults?: number;
    readonly position: SpacePoint;
    readonly shape: CollisionShape3D;
  }): readonly IShapeHit[];
}

type QueryPhysics = IPhysicsContext & {
  readonly directSpaceState: IPhysicsDirectSpaceState;
};

/**
 * PRD-088 is the only route to a collider query. The cast keeps this kit source-compatible with
 * the dependency lane while that public field is being integrated; it is not a fallback query.
 */
export function directSpaceState(physics: IPhysicsContext): IPhysicsDirectSpaceState {
  const state = (physics as QueryPhysics).directSpaceState;
  if (state === undefined) {
    throw new Error("TN_SHOOTER_SPACE_MISSING: @threenative/physics directSpaceState is required.");
  }
  return state;
}
export type GamePhase = "playing" | "dead" | "won" | "lost";

export type GameState = {
  armor: number;
  deaths: number;
  demoTargetAlive: number;
  friendlyPassed: number;
  gameOver: number;
  gameWon: number;
  health: number;
  hitDistanceTenths: number;
  hitNormalXPercent: number;
  hitNormalYPercent: number;
  hitNormalZPercent: number;
  lives: number;
  pickups: number;
  radiusInsideDeaths: number;
  radiusMidAlive: number;
  radiusNearAlive: number;
  radiusOutsideAlive: number;
  respawns: number;
  scanCount: number;
  score: number;
  targetsRemaining: number;
  wave: number;
  wavesCleared: number;
  wallBlocked: number;
  phase: GamePhase;
};
import type { Vector3 } from "three";
import type { Target } from "../entities/Target.js";

export class SpawnPoints {
  readonly points: readonly Vector3[];

  constructor(points: readonly Vector3[]) {
    if (points.length === 0) throw new Error("SpawnPoints requires at least one point.");
    this.points = points.map((point) => point.clone());
  }

  furthestFrom(hostiles: readonly Target[]): Vector3 {
    let best = this.points[0] as Vector3;
    let bestDistance = -1;
    for (const point of this.points) {
      let nearest = Number.POSITIVE_INFINITY;
      for (const hostile of hostiles) {
        if (!hostile.alive) continue;
        nearest = Math.min(nearest, point.distanceToSquared(hostile.mesh.position));
      }
      if (nearest > bestDistance) {
        best = point;
        bestDistance = nearest;
      }
    }
    return best.clone();
  }
}

