const SIGHT_INTERVAL = 0.12;
/** How long the rifleman keeps walking to where it last saw the player before giving up. */
const MEMORY = 2.5;
const REST_PITCH = -0.5;

function approachAngle(current: number, target: number, maxDelta: number): number {
  const delta = Math.atan2(Math.sin(target - current), Math.cos(target - current));
  if (Math.abs(delta) <= maxDelta) return target;
  return current + Math.sign(delta) * maxDelta;
}

/** Yaw for a visual whose local forward is -Z, facing the planar direction `x`/`z`. */
function headingAngle(x: number, z: number): number {
  return Math.atan2(-x, -z);
}

export interface IEnemyOptions {
  /** Patrol loop, walked in order and repeated. The rifleman spawns on the first point. */
  readonly route: readonly Vector3[];
  readonly playerBodyId: number;
  /**
   * Where to look, or `undefined` when the player is not a target at all — dead, despawned,
   * or otherwise off the board. Returning `undefined` makes the rifleman lose sight at once.
   */
  readonly playerEye: () => Vector3 | undefined;
  readonly health?: number;
  /**
   * How far from the middle of its route the rifleman will chase. It closes on the player up
   * to this radius and no further, so it guards a yard instead of following anyone anywhere.
   */
  readonly leash?: number;
  readonly onAlert?: (alerted: boolean) => void;
  readonly onWaypoint?: (reached: number) => void;
}

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy", "rifleman"];
  readonly maxHealth: number;
  health: number;
  alive = true;
  mode: EnemyMode = "patrol";
  waypointsReached = 0;

  #visual: IRiflemanVisual;
  #route: readonly Vector3[];
  #post: Vector3;
  #leash: number;
  #playerBodyId: number;
  #playerEye: () => Vector3 | undefined;
  #onAlert: (alerted: boolean) => void;
  #onWaypoint: (reached: number) => void;
  #waypoint = 1;
  #sightTimer = 0;
  #memory = 0;
  #lastSeen: Vector3 | undefined;
  #alertRange: number | undefined;
  #closed = 0;
  #range = Number.POSITIVE_INFINITY;
  #stridePhase = 0;
  #steering = new Vector3();
  #muzzle = new Vector3();

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createRiflemanVisual>[0],
    options: IEnemyOptions,
  ) {
    const [spawn, second] = options.route;
    if (spawn === undefined || second === undefined) {
      throw new Error("Enemy needs at least two patrol waypoints.");
    }
    this.#route = options.route.map((point) => point.clone());
    this.#post = this.#route
      .reduce((sum, point) => sum.add(point), new Vector3())
      .divideScalar(this.#route.length);
    this.#post.y = 0;
    this.#leash = options.leash ?? 5;
    this.#playerBodyId = options.playerBodyId;
    this.#playerEye = options.playerEye;
    this.#onAlert = options.onAlert ?? (() => undefined);
    this.#onWaypoint = options.onWaypoint ?? (() => undefined);
    this.maxHealth = options.health ?? 60;
    this.health = this.maxHealth;

    this.#visual = createRiflemanVisual(materials, SEAT);
    this.mesh = this.#visual.root;
    this.mesh.position.copy(spawn);
    this.#visual.yaw.rotation.y = headingAngle(second.x - spawn.x, second.z - spawn.z);
    this.#visual.aim.rotation.x = REST_PITCH;
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(HALF_HEIGHT, RADIUS),
    });
  }

  get alerted(): boolean {
    return this.mode === "chase";
  }

  /** World-space muzzle tip — where a shot from this rifle would actually leave it. */
  muzzleOrigin(): Vector3 {
    return this.#visual.muzzle.getWorldPosition(new Vector3());
  }

  update(ctx: GameCtx, dt: number): void {
    if (!this.alive) return;
    this.#sightTimer -= dt;
    if (this.#sightTimer <= 0) {
      this.#sightTimer = SIGHT_INTERVAL;
      this.#look(ctx);
    }
    const eye = this.#playerEye();
    const speed = this.mode === "patrol" ? PATROL_SPEED : CHASE_SPEED;
    const moving = this.#drive(this.#destination(eye), speed, dt);
    this.#cover(eye, moving, dt);
    this.body.moveAndSlide(dt);
    this.#stridePhase += (moving ? speed : 0) * dt * 4.4;
    this.#visual.stride(this.#stridePhase, moving ? 1 : 0);
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    if (this.mode === "chase") this.#onAlert(false);
    this.mode = "patrol";
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alerted: this.alerted ? 1 : 0,
      alive: this.alive,
      // Metres closed on the player since the rifleman first saw them, in tenths.
      closedTenths: Math.round(this.#closed * 10),
      health: this.health,
      mode: this.mode,
      position: this.mesh.position.toArray(),
      rangeTenths: Number.isFinite(this.#range) ? Math.round(this.#range * 10) : -1,
      waypointsReached: this.waypointsReached,
    };
  }

  dispose(): void {
    this.body.dispose();
    this.mesh.removeFromParent();
  }

  /** Range check, then cone check, then one ray — cheapest rejection first. */
  #look(ctx: GameCtx): void {
    const eye = this.#playerEye();
    this.#range = eye === undefined ? Number.POSITIVE_INFINITY : this.#eyePoint().distanceTo(eye);
    if (eye !== undefined && this.#canSee(ctx, eye)) {
      this.#lastSeen = eye.clone();
      this.#memory = MEMORY;
      if (this.#alertRange === undefined) this.#alertRange = this.#range;
      this.#closed = Math.max(this.#closed, this.#alertRange - this.#range);
      if (this.mode !== "chase") {
        this.mode = "chase";
        this.#onAlert(true);
      }
      return;
    }
    if (this.mode === "chase") {
      this.mode = "search";
      this.#onAlert(false);
    }
    if (this.mode !== "search") return;
    this.#memory -= SIGHT_INTERVAL;
    if (this.#memory > 0) return;
    this.mode = "patrol";
    this.#lastSeen = undefined;
    this.#waypoint = this.#nearestWaypoint();
  }

  #canSee(ctx: GameCtx, eye: Vector3): boolean {
    const from = this.#eyePoint();
    const offset = eye.clone().sub(from);
    const distance = offset.length();
    if (distance > SIGHT_RANGE || distance === 0) return false;
    if (offset.divideScalar(distance).dot(this.#facing()) < SIGHT_COS) return false;
    // The rifleman's own body is on the hostile layer and the mask excludes it, so the ray
    // leaves the head without hitting its owner. A wall in the way wins; the player wins.
    const hit = directSpaceState(ctx.physics).intersectRay({
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      from,
      to: eye,
    });
    return hit?.body.id === this.#playerBodyId;
  }

  /** Where the rifleman wants to stand, or `undefined` when it should hold position. */
  #destination(eye: Vector3 | undefined): Vector3 | undefined {
    if (this.mode === "patrol") return this.#route[this.#waypoint % this.#route.length];
    const goal = this.mode === "chase" ? eye : this.#lastSeen;
    if (goal === undefined) return undefined;
    if (this.mode === "chase" && this.#planarDistance(goal) <= STANDOFF) return undefined;
    return this.#leashed(goal);
  }

  #drive(destination: Vector3 | undefined, speed: number, dt: number): boolean {
    const velocity = this.body.velocity;
    velocity.x = 0;
    velocity.z = 0;
    if (destination === undefined) return false;
    this.#steering.set(
      destination.x - this.mesh.position.x,
      0,
      destination.z - this.mesh.position.z,
    );
    const distance = this.#steering.length();
    if (distance <= ARRIVAL) {
      if (this.mode === "patrol") {
        this.waypointsReached += 1;
        this.#waypoint = (this.#waypoint + 1) % this.#route.length;
        this.#onWaypoint(this.waypointsReached);
      }
      return false;
    }
    this.#steering.divideScalar(distance).multiplyScalar(speed);
    velocity.x = this.#steering.x;
    velocity.z = this.#steering.z;
    this.#turnTowards(this.#steering.x, this.#steering.z, dt);
    return true;
  }

  /** Face and cover: the rifle tracks the player when alerted and rests otherwise. */
  #cover(eye: Vector3 | undefined, moving: boolean, dt: number): void {
    const aim = this.#visual.aim;
    const target = this.mode === "chase" ? eye : this.#lastSeen;
    if (this.mode === "patrol" || target === undefined) {
      aim.rotation.x = approachAngle(aim.rotation.x, REST_PITCH, dt * 3);
      return;
    }
    if (!moving) {
      this.#turnTowards(target.x - this.mesh.position.x, target.z - this.mesh.position.z, dt);
    }
    this.#visual.muzzle.getWorldPosition(this.#muzzle);
    const flat = Math.hypot(target.x - this.#muzzle.x, target.z - this.#muzzle.z);
    const pitch = flat === 0 ? 0 : Math.atan2(target.y - this.#muzzle.y, flat);
    aim.rotation.x = approachAngle(aim.rotation.x, pitch, dt * 4);
  }

  #turnTowards(x: number, z: number, dt: number): void {
    if (x === 0 && z === 0) return;
    const yaw = this.#visual.yaw;
    yaw.rotation.y = approachAngle(yaw.rotation.y, headingAngle(x, z), TURN_RATE * dt);
  }

  #facing(): Vector3 {
    const yaw = this.#visual.yaw.rotation.y;
    return new Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
  }

  #eyePoint(): Vector3 {
    return this.mesh.position.clone().add(EYE);
  }

  #planarDistance(point: Vector3): number {
    return Math.hypot(point.x - this.mesh.position.x, point.z - this.mesh.position.z);
  }

  #leashed(goal: Vector3): Vector3 {
    const offset = new Vector3(goal.x - this.#post.x, 0, goal.z - this.#post.z);
    const distance = offset.length();
    if (distance <= this.#leash) return new Vector3(goal.x, this.mesh.position.y, goal.z);
    offset.multiplyScalar(this.#leash / distance).add(this.#post);
    return new Vector3(offset.x, this.mesh.position.y, offset.z);
  }

  #nearestWaypoint(): number {
    let best = 0;
    let bestDistance = Number.POSITIVE_INFINITY;
    this.#route.forEach((point, index) => {
      const distance = this.#planarDistance(point);
      if (distance >= bestDistance) return;
      best = index;
      bestDistance = distance;
    });
    return best;
  }
}
