s = open(p).read()
old_start = s.index("/**\n * The patrolling rifleman.")
new_tail = '''/**
 * The patrolling rifleman. Heading is deliberately *not* a handle here: it belongs on `root`,
 * which is the transform the physics body round-trips and the one a playtest observes, so the
 * figure cannot end up facing somewhere the recorded rotation disagrees with. What is left is
 * weapon elevation on `aim` and the walk cycle the four limb pivots `stride` drives.
 */
export interface IRiflemanVisual {
  /**
   * Parent this onto the body and rotate it about Y to face a heading. Its origin is the
   * capsule centre, not the figure's feet, and its local forward is -Z — so the right hand,
   * the one holding the rifle, is at +X.
   */
  readonly root: Group;
  /** Right shoulder pivot. Rotate about X to raise the rifle; positive lifts the muzzle. */
  readonly aim: Group;
  /** Barrel tip. Read it with `getWorldPosition` for a muzzle-accurate shot origin. */
  readonly muzzle: Object3D;
  /** Walk cycle. `phase` advances with distance travelled, `amount` scales the swing to 0..1. */
  readonly stride: (phase: number, amount: number) => void;
}

/** Total height of the figure from its feet, so the entity can seat it on its capsule. */
export const RIFLEMAN_HEIGHT = 1.82;
/** Eye height from the figure's feet, for line-of-sight rays that leave the head. */
export const RIFLEMAN_EYE_HEIGHT = 1.66;

function pivot(parent: Group, x: number, y: number, z: number): Group {
  const group = new Group();
  group.position.set(x, y, z);
  parent.add(group);
  return group;
}

function limb(
  parent: Group,
  width: number,
  height: number,
  depth: number,
  material: Material,
  y: number,
  z = 0,
): Mesh {
  const mesh = block(width, height, depth, material);
  mesh.position.set(0, y, z);
  parent.add(mesh);
  return mesh;
}

function createRifle(materials: ShooterMaterials): { group: Group; muzzle: Object3D } {
  const group = new Group();
  group.name = "rifle";
  const part = (
    width: number,
    height: number,
    depth: number,
    y: number,
    z: number,
    material: Material,
  ): void => {
    const mesh = block(width, height, depth, material);
    mesh.position.set(0, y, z);
    group.add(mesh);
  };
  part(0.1, 0.14, 0.6, 0, 0, materials.shadow);
  part(0.09, 0.13, 0.26, -0.01, 0.4, materials.shadow);
  part(0.08, 0.18, 0.11, -0.14, 0.13, materials.shadow);
  part(0.08, 0.24, 0.1, -0.17, -0.06, materials.shadow);
  part(0.05, 0.07, 0.12, 0.1, -0.12, materials.trim);
  const barrel = new Mesh(
    new CylinderGeometry(0.032, 0.036, 0.54, 6).rotateX(Math.PI / 2),
    materials.shadow,
  );
  barrel.position.set(0, 0.01, -0.57);
  barrel.castShadow = true;
  group.add(barrel);
  const muzzle = new Object3D();
  muzzle.name = "rifle-muzzle";
  muzzle.position.set(0, 0.01, -0.86);
  group.add(muzzle);
  return { group, muzzle };
}

export function createRiflemanVisual(materials: ShooterMaterials, seat: number): IRiflemanVisual {
  const root = new Group();
  root.name = "rifleman";
  // The capsule is centred on the body origin, so drop the figure until its feet reach the
  // bottom cap instead of leaving it hovering a half-capsule above the floor.
  const body = pivot(root, 0, -seat, 0);
  body.name = "rifleman-body";

  const hipLeft = pivot(body, -0.17, 0.76, 0);
  const hipRight = pivot(body, 0.17, 0.76, 0);
  limb(hipLeft, 0.24, 0.76, 0.28, materials.hostile, -0.38);
  limb(hipRight, 0.24, 0.76, 0.28, materials.hostile, -0.38);
  limb(body, 0.56, 0.18, 0.36, materials.shadow, 0.85);
  limb(body, 0.64, 0.7, 0.4, materials.hostile, 1.26);
  limb(body, 0.46, 0.06, 0.06, materials.trim, 1.36, -0.21);
  limb(body, 0.36, 0.32, 0.34, materials.hostile, 1.66);
  limb(body, 0.3, 0.1, 0.06, materials.trim, 1.69, -0.18);

  const shoulderLeft = pivot(body, -0.4, 1.42, 0);
  limb(shoulderLeft, 0.16, 0.62, 0.18, materials.hostile, -0.31);

  const aim = pivot(body, 0.4, 1.42, 0);
  aim.name = "rifleman-aim";
  limb(aim, 0.16, 0.34, 0.18, materials.hostile, -0.15);
  limb(aim, 0.15, 0.15, 0.36, materials.hostile, -0.26, -0.14);
  limb(aim, 0.13, 0.13, 0.13, materials.trim, -0.26, -0.33);
  const rifle = createRifle(materials);
  rifle.group.position.set(0, -0.26, -0.42);
  aim.add(rifle.group);

  const stride = (phase: number, amount: number): void => {
    const swing = Math.sin(phase) * 0.5 * amount;
    hipLeft.rotation.x = swing;
    hipRight.rotation.x = -swing;
    shoulderLeft.rotation.x = -swing * 0.7;
  };
  stride(0, 0);

  return { aim, muzzle: rifle.muzzle, root, stride };
}
