  1	import type { ICtx } from "@threenative/core";
  2	import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
  3	import { type Group, Vector3 } from "three";
  4	import { directSpaceState } from "../physics.js";
  5	import {
  6	  type IRiflemanVisual,
  7	  RIFLEMAN_EYE_HEIGHT,
  8	  createRiflemanVisual,
  9	} from "../render/shapes.js";
 10	import type { GameState } from "../state.js";
 11	import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";
 12	
 13	type GameCtx = ICtx<GameState, IPhysicsContext>;
 14	
 15	/** What the rifleman is doing right now. */
 16	export type EnemyMode = "patrol" | "chase" | "search";
 17	
 18	const HALF_HEIGHT = 0.45;
 19	const RADIUS = 0.38;
 20	const SEAT = HALF_HEIGHT + RADIUS;
 21	const EYE = new Vector3(0, RIFLEMAN_EYE_HEIGHT - SEAT, 0);
 22	
 23	const PATROL_SPEED = 2;
 24	const CHASE_SPEED = 3.4;
 25	const TURN_RATE = 4.6;
 26	const ARRIVAL = 0.7;
 27	/** How close the rifleman closes before it holds position and just keeps the player covered. */
 28	const STANDOFF = 2.6;
 29	const SIGHT_RANGE = 14;
 30	/** Half of a 100° cone, as a dot product against the facing direction. */
 31	const SIGHT_COS = Math.cos((50 * Math.PI) / 180);
 32	const SIGHT_INTERVAL = 0.12;
 33	/** How long the rifleman keeps walking to where it last saw the player before giving up. */
 34	const MEMORY = 2.5;
 35	const REST_PITCH = -0.5;
 36	
 37	function approachAngle(current: number, target: number, maxDelta: number): number {
 38	  const delta = Math.atan2(Math.sin(target - current), Math.cos(target - current));
 39	  if (Math.abs(delta) <= maxDelta) return target;
 40	  return current + Math.sign(delta) * maxDelta;
 41	}
 42	
 43	/** Yaw for a visual whose local forward is -Z, facing the planar direction `x`/`z`. */
 44	function headingAngle(x: number, z: number): number {
 45	  return Math.atan2(-x, -z);
 46	}
 47	
 48	export interface IEnemyOptions {
 49	  /** Patrol loop, walked in order and repeated. The rifleman spawns on the first point. */
 50	  readonly route: readonly Vector3[];
 51	  readonly playerBodyId: number;
 52	  /**
 53	   * Where to look, or `undefined` when the player is not a target at all — dead, despawned,
 54	   * or otherwise off the board. Returning `undefined` makes the rifleman lose sight at once.
 55	   */
 56	  readonly playerEye: () => Vector3 | undefined;
 57	  readonly health?: number;
 58	  /**
 59	   * How far from the middle of its route the rifleman will chase. It closes on the player up
 60	   * to this radius and no further, so it guards a yard instead of following anyone anywhere.
 61	   */
 62	  readonly leash?: number;
 63	  readonly onAlert?: (alerted: boolean) => void;
 64	  readonly onWaypoint?: (reached: number) => void;
 65	}
 66	
 67	export class Enemy {
 68	  readonly mesh: Group;
 69	  readonly body: CharacterBody3D;
 70	  readonly tags = ["hostile", "enemy", "rifleman"];
 71	  readonly maxHealth: number;
 72	  health: number;
 73	  alive = true;
 74	  mode: EnemyMode = "patrol";
 75	  waypointsReached = 0;
 76	
 77	  #visual: IRiflemanVisual;
 78	  #route: readonly Vector3[];
 79	  #post: Vector3;
 80	  #leash: number;
 81	  #playerBodyId: number;
 82	  #playerEye: () => Vector3 | undefined;
 83	  #onAlert: (alerted: boolean) => void;
 84	  #onWaypoint: (reached: number) => void;
 85	  #waypoint = 1;
 86	  #sightTimer = 0;
 87	  #memory = 0;
 88	  #lastSeen: Vector3 | undefined;
 89	  #alertRange: number | undefined;
 90	  #closed = 0;
 91	  #range = Number.POSITIVE_INFINITY;
 92	  #stridePhase = 0;
 93	  #steering = new Vector3();
 94	  #muzzle = new Vector3();
 95	
 96	  constructor(
 97	    ctx: GameCtx,
 98	    materials: Parameters<typeof createRiflemanVisual>[0],
 99	    options: IEnemyOptions,
100	  ) {
101	    const [spawn, second] = options.route;
102	    if (spawn === undefined || second === undefined) {
103	      throw new Error("Enemy needs at least two patrol waypoints.");
104	    }
105	    this.#route = options.route.map((point) => point.clone());
106	    this.#post = this.#route
107	      .reduce((sum, point) => sum.add(point), new Vector3())
108	      .divideScalar(this.#route.length);
109	    this.#post.y = 0;
110	    this.#leash = options.leash ?? 5;
111	    this.#playerBodyId = options.playerBodyId;
112	    this.#playerEye = options.playerEye;
113	    this.#onAlert = options.onAlert ?? (() => undefined);
114	    this.#onWaypoint = options.onWaypoint ?? (() => undefined);
115	    this.maxHealth = options.health ?? 60;
116	    this.health = this.maxHealth;
117	
118	    this.#visual = createRiflemanVisual(materials, SEAT);
119	    this.mesh = this.#visual.root;
120	    this.mesh.position.copy(spawn);
121	    this.mesh.rotation.y = headingAngle(second.x - spawn.x, second.z - spawn.z);
122	    this.#visual.aim.rotation.x = REST_PITCH;
123	    ctx.add(this.mesh);
124	    this.body = new CharacterBody3D({
125	      autostep: { maxHeight: 0.25, minWidth: 0.18 },
126	      collisionLayer: HOSTILE_LAYER,
127	      collisionMask: WORLD_LAYER | PLAYER_LAYER,
128	      object: this.mesh,
129	      physics: ctx.physics,
130	      shape: CollisionShape3D.capsule(HALF_HEIGHT, RADIUS),
131	    });
132	  }
133	
134	  get alerted(): boolean {
135	    return this.mode === "chase";
136	  }
137	
138	  /** World-space muzzle tip — where a shot from this rifle would actually leave it. */
139	  muzzleOrigin(): Vector3 {
140	    return this.#visual.muzzle.getWorldPosition(new Vector3());
141	  }
142	
143	  update(ctx: GameCtx, dt: number): void {
144	    if (!this.alive) return;
145	    this.#sightTimer -= dt;
146	    if (this.#sightTimer <= 0) {
147	      this.#sightTimer = SIGHT_INTERVAL;
148	      this.#look(ctx);
149	    }
150	    const eye = this.#playerEye();
151	    const speed = this.mode === "patrol" ? PATROL_SPEED : CHASE_SPEED;
152	    const moving = this.#drive(this.#destination(eye), speed, dt);
153	    this.#cover(eye, moving, dt);
154	    this.body.moveAndSlide(dt);
155	    this.#stridePhase += (moving ? speed : 0) * dt * 4.4;
156	    this.#visual.stride(this.#stridePhase, moving ? 1 : 0);
157	  }
158	
159	  takeDamage(amount: number): boolean {
160	    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
161	    this.health = Math.max(0, this.health - amount);
162	    if (this.health > 0) return false;
163	    this.alive = false;
164	    this.mesh.visible = false;
165	    this.body.velocity.set(0, 0, 0);
166	    if (this.mode === "chase") this.#onAlert(false);
167	    this.mode = "patrol";
168	    return true;
169	  }
170	
171	  debug(): Record<string, unknown> {
172	    return {
173	      alerted: this.alerted ? 1 : 0,
174	      alive: this.alive,
175	      // Metres closed on the player since the rifleman first saw them, in tenths.
176	      closedTenths: Math.round(this.#closed * 10),
177	      health: this.health,
178	      mode: this.mode,
179	      position: this.mesh.position.toArray(),
180	      rangeTenths: Number.isFinite(this.#range) ? Math.round(this.#range * 10) : -1,
181	      waypointsReached: this.waypointsReached,
182	    };
183	  }
184	
185	  dispose(): void {
186	    this.body.dispose();
187	    this.mesh.removeFromParent();
188	  }
189	
190	  /** Range check, then cone check, then one ray — cheapest rejection first. */
191	  #look(ctx: GameCtx): void {
192	    const eye = this.#playerEye();
193	    this.#range = eye === undefined ? Number.POSITIVE_INFINITY : this.#eyePoint().distanceTo(eye);
194	    if (eye !== undefined && this.#canSee(ctx, eye)) {
195	      this.#lastSeen = eye.clone();
196	      this.#memory = MEMORY;
197	      if (this.#alertRange === undefined) this.#alertRange = this.#range;
198	      this.#closed = Math.max(this.#closed, this.#alertRange - this.#range);
199	      if (this.mode !== "chase") {
200	        this.mode = "chase";
201	        this.#onAlert(true);
202	      }
203	      return;
204	    }
205	    if (this.mode === "chase") {
206	      this.mode = "search";
207	      this.#onAlert(false);
208	    }
209	    if (this.mode !== "search") return;
210	    this.#memory -= SIGHT_INTERVAL;
211	    if (this.#memory > 0) return;
212	    this.mode = "patrol";
213	    this.#lastSeen = undefined;
214	    this.#waypoint = this.#nearestWaypoint();
215	  }
216	
217	  #canSee(ctx: GameCtx, eye: Vector3): boolean {
218	    const from = this.#eyePoint();
219	    const offset = eye.clone().sub(from);
220	    const distance = offset.length();
221	    if (distance > SIGHT_RANGE || distance === 0) return false;
222	    if (offset.divideScalar(distance).dot(this.#facing()) < SIGHT_COS) return false;
223	    // The rifleman's own body is on the hostile layer and the mask excludes it, so the ray
224	    // leaves the head without hitting its owner. A wall in the way wins; the player wins.
225	    const hit = directSpaceState(ctx.physics).intersectRay({
226	      collisionMask: WORLD_LAYER | PLAYER_LAYER,
227	      from,
228	      to: eye,
229	    });
230	    return hit?.body.id === this.#playerBodyId;
231	  }
232	
233	  /** Where the rifleman wants to stand, or `undefined` when it should hold position. */
234	  #destination(eye: Vector3 | undefined): Vector3 | undefined {
235	    if (this.mode === "patrol") return this.#route[this.#waypoint % this.#route.length];
236	    const goal = this.mode === "chase" ? eye : this.#lastSeen;
237	    if (goal === undefined) return undefined;
238	    if (this.mode === "chase" && this.#planarDistance(goal) <= STANDOFF) return undefined;
239	    return this.#leashed(goal);
240	  }
241	
242	  #drive(destination: Vector3 | undefined, speed: number, dt: number): boolean {
243	    const velocity = this.body.velocity;
244	    velocity.x = 0;
245	    velocity.z = 0;
246	    if (destination === undefined) return false;
247	    this.#steering.set(
248	      destination.x - this.mesh.position.x,
249	      0,
250	      destination.z - this.mesh.position.z,
251	    );
252	    const distance = this.#steering.length();
253	    if (distance <= ARRIVAL) {
254	      if (this.mode === "patrol") {
255	        this.waypointsReached += 1;
256	        this.#waypoint = (this.#waypoint + 1) % this.#route.length;
257	        this.#onWaypoint(this.waypointsReached);
258	      }
259	      return false;
260	    }
261	    this.#steering.divideScalar(distance).multiplyScalar(speed);
262	    velocity.x = this.#steering.x;
263	    velocity.z = this.#steering.z;
264	    this.#turnTowards(this.#steering.x, this.#steering.z, dt);
265	    return true;
266	  }
267	
268	  /** Face and cover: the rifle tracks the player when alerted and rests otherwise. */
269	  #cover(eye: Vector3 | undefined, moving: boolean, dt: number): void {
270	    const aim = this.#visual.aim;
271	    const target = this.mode === "chase" ? eye : this.#lastSeen;
272	    if (this.mode === "patrol" || target === undefined) {
273	      aim.rotation.x = approachAngle(aim.rotation.x, REST_PITCH, dt * 3);
274	      return;
275	    }
276	    if (!moving) {
277	      this.#turnTowards(target.x - this.mesh.position.x, target.z - this.mesh.position.z, dt);
278	    }
279	    this.#visual.muzzle.getWorldPosition(this.#muzzle);
280	    const flat = Math.hypot(target.x - this.#muzzle.x, target.z - this.#muzzle.z);
281	    const pitch = flat === 0 ? 0 : Math.atan2(target.y - this.#muzzle.y, flat);
282	    aim.rotation.x = approachAngle(aim.rotation.x, pitch, dt * 4);
283	  }
284	
285	  /**
286	   * Heading goes on the body's own transform, not on a child, so the rotation physics writes
287	   * back and a playtest observes is the direction the rifleman is actually facing.
288	   */
289	  #turnTowards(x: number, z: number, dt: number): void {
290	    if (x === 0 && z === 0) return;
291	    const current = this.mesh.rotation.y;
292	    this.mesh.rotation.y = approachAngle(current, headingAngle(x, z), TURN_RATE * dt);
293	  }
294	
295	  #facing(): Vector3 {
296	    const yaw = this.mesh.rotation.y;
297	    return new Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
298	  }
299	
300	  #eyePoint(): Vector3 {
301	    return this.mesh.position.clone().add(EYE);
302	  }
303	
304	  #planarDistance(point: Vector3): number {
305	    return Math.hypot(point.x - this.mesh.position.x, point.z - this.mesh.position.z);
306	  }
307	
308	  #leashed(goal: Vector3): Vector3 {
309	    const offset = new Vector3(goal.x - this.#post.x, 0, goal.z - this.#post.z);
310	    const distance = offset.length();
311	    if (distance <= this.#leash) return new Vector3(goal.x, this.mesh.position.y, goal.z);
312	    offset.multiplyScalar(this.#leash / distance).add(this.#post);
313	    return new Vector3(offset.x, this.mesh.position.y, offset.z);
314	  }
315	
316	  #nearestWaypoint(): number {
317	    let best = 0;
318	    let bestDistance = Number.POSITIVE_INFINITY;
319	    this.#route.forEach((point, index) => {
320	      const distance = this.#planarDistance(point);
321	      if (distance >= bestDistance) return;
322	      best = index;
323	      bestDistance = distance;
324	    });
325	    return best;
326	  }
327	}

